fn case(i: usize) -> Case {
    let (name, text) = CASES[i];
    parse_case(&serde_json::from_str(text).unwrap_or_else(|e| panic!("{name}: {e}"))).unwrap_or_else(|e| panic!("{name}: {e}"))
}

/// Every edit SolveCraft took holds the requested values.
fn assert_edits_hold(name: &str, c: &Case, edits: &[Snap]) {
    for (i, (snap, edit)) in edits.iter().zip(&c.edits).enumerate().filter(|(_, (s, _))| s.took) {
        let missing = unheld(c, &snap.points, edit);
        assert!(missing.is_empty(), "{name} edit {i}: {missing:?}");
    }
}

#[test]
fn every_case_builds_and_solves_where_it_was_drawn() {
    for (i, (name, _)) in CASES.iter().enumerate() {
        let c = case(i);
        let mut s = build(&c).unwrap_or_else(|e| panic!("{name}: {e}"));
        let (solved, points) = inspect(&mut s, &c).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert!(solved, "{name}: the initial sketch does not solve");
        for (n, want) in &c.points {
            let got = points[n];
            // The case's dimension values are rounded to 1e-6 mm, so the solve moves points a
            // little, more where the geometry amplifies it (an apex near its base 1.3e-6 mm,
            // the triconnected linkage 1.1e-5 mm); well inside `SAME_TOL`.
            assert!((got[0] - want[0]).hypot(got[1] - want[1]) < 1e-4, "{name}: {n} at {got:?}, drawn at {want:?}");
        }
        // The dimensions carry the case's names (as Fusion's parameters do).
        let params = s.execute("parameters.list", &json!({})).unwrap();
        for d in &c.dims {
            assert!(params["parameters"].as_array().unwrap().iter().any(|p| p["name"] == d.name.as_str()), "{name}: no parameter {}", d.name);
        }
    }
}

#[test]
fn every_case_replays_its_edits_together_and_one_by_one() {
    for (i, (name, _)) in CASES.iter().enumerate() {
        let c = case(i);
        for mode in [Mode::Together, Mode::OneByOne] {
            let (initial, edits) = replay(&c, &vec![mode; c.edits.len()]).unwrap_or_else(|e| panic!("{name}: {e}"));
            assert!(initial.took, "{name}");
            assert_eq!(edits.len(), c.edits.len());
            assert!(edits.iter().any(|e| e.took), "{name} ({mode:?}): no edit took: {:?}", edits.iter().map(|e| &e.errors).collect::<Vec<_>>());
            assert_edits_hold(name, &c, &edits);
        }
    }
}

/// The full local cases (plan/ is not committed: skipped where the data is absent).
#[test]
fn local_cases_replay_when_present() {
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../plan/fusion/solver-oracle");
    let Ok(entries) = std::fs::read_dir(&dir) else { return };
    let mut dirs: Vec<_> = entries.flatten().map(|e| e.path()).filter(|p| p.join("case.json").is_file()).collect();
    dirs.sort();
    for d in dirs {
        let name = d.display().to_string();
        let c = parse_case(&read_json(&format!("{name}/case.json")).unwrap()).unwrap_or_else(|e| panic!("{name}: {e}"));
        let (initial, edits) = replay(&c, &[]).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert!(initial.took, "{name}");
        assert_edits_hold(&name, &c, &edits);
    }
}

fn snap(took: bool, pts: &[(&str, Pt)]) -> Snap {
    Snap { took, points: pts.iter().map(|(n, p)| (n.to_string(), *p)).collect(), errors: vec![] }
}

#[test]
fn classifier_tells_same_mirrored_different_and_refusals_apart() {
    let c = case(0);
    let o = Orientations::of(&c).unwrap();
    assert_eq!(o.turns, vec![["B".to_string(), "C".to_string(), "O".to_string()]]);
    let ours = snap(true, &[("O", [0.0, 0.0]), ("B", [40.0, 0.0]), ("C", [30.0, 20.0])]);
    let class = |fusion: &Snap| classify(&o, &ours, fusion).0;
    // Within 1e-3 mm: the same solution.
    assert_eq!(class(&snap(true, &[("O", [0.0, 0.0]), ("B", [40.0, 0.0]), ("C", [30.0005, 20.0])])), Class::Same);
    // The apex on the other side of the base.
    let (k, detail) = classify(&o, &ours, &snap(true, &[("O", [0.0, 0.0]), ("B", [40.0, 0.0]), ("C", [30.0, -20.0])]));
    assert_eq!(k, Class::Mirrored);
    assert!(detail.contains("turn B,C,O"), "{detail}");
    // Elsewhere on the same side.
    assert_eq!(class(&snap(true, &[("O", [0.0, 0.0]), ("B", [40.0, 0.0]), ("C", [10.0, 20.0])])), Class::Different);
    // Refusals: only `took` matters.
    let far = snap(false, &[("O", [0.0, 0.0]), ("B", [40.0, 0.0]), ("C", [-5.0, 1.0])]);
    assert_eq!(class(&far), Class::FusionRefused);
    let refused = Snap { took: false, ..ours.clone() };
    assert_eq!(classify(&o, &refused, &ours).0, Class::WeRefused);
    assert_eq!(classify(&o, &refused, &far).0, Class::BothRefused);
}

#[test]
fn an_offset_on_the_other_side_is_mirrored() {
    let c = case(6);
    let o = Orientations::of(&c).unwrap();
    let ours = snap(true, &[("O", [0.0, 0.0]), ("A", [50.0, 0.0]), ("B", [50.5, 15.0])]);
    let (k, detail) = classify(&o, &ours, &snap(true, &[("O", [0.0, 0.0]), ("A", [50.0, 0.0]), ("B", [49.5, 15.0])]));
    assert_eq!(k, Class::Mirrored);
    assert!(detail.contains("x-side A→B"), "{detail}");
    // A horizontal line that reverses is a mirror too.
    let (k, detail) = classify(&o, &ours, &snap(true, &[("O", [0.0, 0.0]), ("A", [-50.0, 0.0]), ("B", [-49.5, 15.0])]));
    assert_eq!(k, Class::Mirrored);
    assert!(detail.contains("x-side O→A"), "{detail}");
}

#[test]
fn an_arcs_centre_and_ends_are_a_compared_turn() {
    let c = case(5);
    let o = Orientations::of(&c).unwrap();
    assert!(o.turns.iter().any(|t| t.contains(&"c0".to_string()) && t.contains(&"l1".to_string()) && t.contains(&"b0".to_string())));
}

/// A scratch directory with a case and a measure.json made from our own replay (so every edit
/// matches), with edit 1 then edited to Fusion's taste.
fn measured_dir(tag: &str, edit: impl FnOnce(&mut Value)) -> std::path::PathBuf {
    let c = case(0);
    let (initial, edits) = replay(&c, &[]).unwrap();
    let snap_json = |s: &Snap| json!({"points": s.points, "took": s.took, "mode": "together"});
    let mut m = json!({"initial": snap_json(&initial), "edits": edits.iter().map(snap_json).collect::<Vec<_>>()});
    edit(&mut m);
    let dir = std::env::temp_dir().join(format!("solvecraft-solver-oracle-{tag}-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    std::fs::write(dir.join("case.json"), CASES[0].1).unwrap();
    std::fs::write(dir.join("measure.json"), m.to_string()).unwrap();
    dir
}

#[test]
fn a_measured_case_is_classified_edit_by_edit() {
    let dir = measured_dir("classes", |m| {
        let c = &mut m["edits"][1]["points"]["C"];
        let y = c[1].as_f64().unwrap();
        c[1] = json!(-y);
        m["edits"][0]["took"] = json!(false);
    });
    let r = check_case(dir.to_str().unwrap());
    let _ = std::fs::remove_dir_all(&dir);
    assert!(r.get("error").is_none(), "{r}");
    assert_eq!(r["counts"]["fusion_refused"], 1, "{r}");
    assert_eq!(r["counts"]["mirrored"], 1, "{r}");
    assert_eq!(r["results"][1]["class"], "mirrored");
    assert!(r["results"][1]["ours"]["C"].is_array());
}

#[test]
fn a_measure_that_does_not_fit_the_case_is_an_error() {
    let dir = measured_dir("short", |m| {
        m["edits"].as_array_mut().unwrap().pop();
    });
    let r = check_case(dir.to_str().unwrap());
    let _ = std::fs::remove_dir_all(&dir);
    assert!(r["error"].as_str().unwrap().contains("edits"), "{r}");

    let dir = measured_dir("moved", |m| m["initial"]["points"]["C"] = json!([18.0, -2.5]));
    let r = check_case(dir.to_str().unwrap());
    let _ = std::fs::remove_dir_all(&dir);
    assert!(r["error"].as_str().unwrap().contains("initial"), "{r}");
}

#[test]
fn an_unmeasured_case_reports_the_replay_only() {
    let dir = std::env::temp_dir().join(format!("solvecraft-solver-oracle-unmeasured-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    std::fs::write(dir.join("case.json"), CASES[1].1).unwrap();
    let r = check_case(dir.to_str().unwrap());
    let _ = std::fs::remove_dir_all(&dir);
    assert_eq!(r["measured"], false, "{r}");
    assert_eq!(r["edits"], 2);
}

/// Case 01 with other edits.
fn apex_with_edits(edits: Value) -> Case {
    let mut v: Value = serde_json::from_str(CASES[0].1).unwrap();
    v["edits"] = edits;
    parse_case(&v).unwrap()
}

#[test]
fn a_refused_edit_is_reverted_before_the_next() {
    // dOC = 5 cannot close the triangle (5 + 22.1 < 40): refused, and Fusion keeps the old value.
    // dBC = 30 then closes it with the old dOC (18.2), but not with 5 (5 + 30 < 40).
    let c = apex_with_edits(json!([{"dOC": 5.0}, {"dBC": 30.0}]));
    let (_, edits) = replay(&c, &[]).unwrap();
    assert!(!edits[0].took, "{:?}", edits[0]);
    assert!(edits[1].took, "{:?}", edits[1]);
    let d = c.dims.iter().find(|d| d.name == "dOC").unwrap();
    assert!((dim_value(&c, &edits[1].points, d).unwrap() - 18.172782).abs() < 1e-6);
}

#[test]
fn an_edit_takes_together_but_not_through_an_unsolvable_step() {
    // dOC = 65 alone cannot close the triangle (22.1 + 40 < 65); with dBC = 30 it can. Set
    // together the edit takes; set one by one the first value is refused (the engine keeps a
    // sketch's values when they leave it unsolved, as Fusion does per dimension), so the edit
    // does not reach its values.
    let c = apex_with_edits(json!([{"dOC": 65.0, "dBC": 30.0}]));
    let (_, together) = replay(&c, &[Mode::Together]).unwrap();
    assert!(together[0].took, "{:?}", together[0]);
    assert_edits_hold("together", &c, &together);
    let (_, one_by_one) = replay(&c, &[Mode::OneByOne]).unwrap();
    assert!(!one_by_one[0].took, "{:?}", one_by_one[0]);
}

#[test]
fn an_edit_whose_values_do_not_hold_is_refused() {
    let c = apex_with_edits(json!([{"dOC": 30.0, "dBC": 30.0}]));
    let mut s = build(&c).unwrap();
    let (_, mut pts) = inspect(&mut s, &c).unwrap();
    // The drawn sketch does not measure the edit's values: both are reported.
    assert_eq!(unheld(&c, &pts, &c.edits[0]).len(), 2);
    pts.insert("C".into(), [20.0, 500.0_f64.sqrt()]);
    assert!(unheld(&c, &pts, &c.edits[0]).is_empty());
}

#[test]
fn too_many_relations_are_an_error_not_an_explosion() {
    let n = 1000;
    let points: serde_json::Map<String, Value> = (0..n).map(|i| (format!("P{i}"), json!([i as f64, (i * i % 97) as f64]))).collect();
    let fixed: Vec<String> = (0..n).map(|i| format!("P{i}")).collect();
    let c =
        parse_case(&json!({"points": points, "fixed": fixed, "lines": [], "arcs": [], "constraints": [], "dimensions": [], "edits": []})).unwrap();
    let t = std::time::Instant::now();
    let e = Orientations::of(&c).err().unwrap();
    assert!(e.contains("too many"), "{e}");
    assert!(t.elapsed().as_secs() < 5);
}

#[test]
fn a_measure_edit_without_a_known_mode_is_an_error() {
    let c = case(0);
    let pts = json!({"O": [0, 0], "B": [40, 0], "C": [18, 2.5]});
    for mode in [json!(null), json!("sideways")] {
        let mut edits = vec![json!({"points": pts, "took": true, "mode": "together"}); 2];
        edits[1]["mode"] = mode.clone();
        let e = parse_measure(&json!({"initial": {"points": pts}, "edits": edits}), &c).err().unwrap();
        assert!(e.contains("edit 1"), "{mode}: {e}");
    }
}

#[test]
fn hostile_cases_are_refused_not_crashed() {
    for bad in [
        r#"{}"#,
        r#"{"points":{"A":[0,"x"]},"fixed":[],"lines":[],"arcs":[],"constraints":[],"dimensions":[],"edits":[]}"#,
        r#"{"points":{"A":[0,0]},"fixed":["Z"],"lines":[],"arcs":[],"constraints":[],"dimensions":[],"edits":[]}"#,
        r#"{"points":{"A":[0,0]},"fixed":[],"lines":[["l","A","Z"]],"arcs":[],"constraints":[],"dimensions":[],"edits":[]}"#,
        r#"{"points":{"A":[0,0],"B":[1,0]},"fixed":[],"lines":[],"arcs":[],"constraints":[{"type":"spline"}],"dimensions":[],"edits":[]}"#,
        r#"{"points":{"A":[0,0],"B":[1,0]},"fixed":[],"lines":[],"arcs":[],"constraints":[],"dimensions":[{"name":"d","type":"distance","a":"A","b":"B","value":1}],"edits":[{"e":2}]}"#,
        r#"{"points":{"A":[0,0],"B":[1,0]},"fixed":[],"lines":[],"arcs":[],"constraints":[],"dimensions":[{"name":"d","type":"angle","a":"A","b":"B","value":1}],"edits":[]}"#,
    ] {
        assert!(parse_case(&serde_json::from_str(bad).unwrap()).is_err(), "{bad}");
    }
    // Parsed, but the engine refuses it: an error, not a crash.
    let c = parse_case(&json!({"points": {"A": [0, 0], "B": [1, 0]}, "fixed": [], "lines": [], "arcs": [{"id": "a", "center": "A", "start": "A", "end": "B"}], "constraints": [], "dimensions": [], "edits": []})).unwrap();
    assert!(build(&c).is_err());
}
